DO $ba$
DECLARE expected_delta bigint; packs jsonb := $pack$[{"codigo":"S22BA-448-1","legacy_id":448,"relacionadas":["S22C-C02","S22E-C01"],"coberturas":[{"legacy_id":448,"estado_cobertura":"PARCIAL","residual":"Operación OTP_OP_B2B_AUTH_PASSWORD_RECOVERY_EMAIL, política OTP_POL_B2B_AUTH_EMAIL_BREVO, ruta B2B_ROUTE_AUTH_RECOVERY_VERIFY, error LF-B2B-AUTH-006 y política SEC-B2B-AUTH-PROVIDER-ARCHITECTURE existen pero CANDIDATO; falta evidencia de emisión/consumo de grant opaco temporal de uso único y binding runtime. No autoriza producción.","diferencias":"Cubre verificación de recuperación y contexto restringido entre pantallas B2B de origen; fuente CANDIDATO, contratos físicos candidatos y runtime pendiente."}],"paquete":{"tipo":"NUEVA","codigo":"S22BA-448-1","clave":"s22ba_legacy_448_0","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"B2B_AUTENTICACION","modo":"HEREDA","dueno":"TECNICO","titulo":"OTP de recuperación verificado y contexto restringido B2B","descripcion":"BLOQUEAR verificación B2B-AUTH-006 y acceso a B2B-AUTH-003 si OTP PASSWORD_RECOVERY no es verificado por servidor mediante operación, política, ruta y arquitectura de seguridad gobernadas; solo verificación válida emite contexto opaco temporal de uso único PASSWORD_UPDATE_ONLY. No concede acceso operativo, no satisface MFA, cliente no puede promoverlo. Código inválido, vencido, agotado o contexto reutilizado no emite grant y se normaliza por error canónico de recuperación sin revelar existencia ni estado de cuenta. No enviar payload nueva contraseña antes de verificar. Referencias por código a lf_ops.otp_operaciones, otp_politicas, rutas, errores_catalogo y politicas_seguridad; no fijar IDs numéricos ni seleccionar proveedor. Alcance condicionado a recuperación en B2B_AUTENTICACION; fuente CANDIDATO, no autoriza producción ni modifica IG.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/448","solicitante":"Cristhian / Claude S22-BA"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ba_recovery_verification_gate"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ba_recovery_otp_not_server_verified"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ba_recovery_context_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_grant_not_opaque_single_use"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_grant_not_password_only"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_grant_not_temporary"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_operational_access"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_mfa_satisfied"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_client_promotion"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_invalid_grant_issued"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_error_not_canonical"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_account_exposed"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_password_payload_before_verify"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ba_recovery_policy_route_operation_mismatch"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_b