SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":true,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":true,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":true,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":true,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":true,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":true,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":true,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":true,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":true,"ba_recovery_policy_route_operation_mismatch":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":true,"ba_recovery_otp_not_server_verified":false,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":false,"ba_recovery_otp_not_server_verified":true,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]},"hash_paquete":"3d4d6fbbfd0269a2114e783e94c0ca2899c75507957f8c3891e602c406700a40","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb; v integer;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo'; v:=1;
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM v THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,v);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=v LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 22:43 Lima: Revisado conforme; S22BA-448-1, 448 parcial; juicio V3 independiente');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22BA_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22BA_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=v AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22BA_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; v:=1; h:=lf_ops.nucleo_hash_paquete_v1(cd,v);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22BA_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22BA_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,v,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 22:43 Lima'),h,'GPT / Claude S22-BA independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22BA_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22BA_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22BA_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22BA_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $ba$;
COMMIT;
